<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionSnippetVO;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionLocaleVO;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionSubjectVO;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionContentHtmlVO;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionContentTextVO;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionVersionVO;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Usecase\Retrieve\SnippetVersionRetrieveResult;
use PHPUnit\Framework\TestCase;

final class SnippetVersionRetrieveResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new SnippetVersionRetrieveResult();
        $snippetOneValue = new SnippetRef('one');
        $snippetOtherValue = new SnippetRef('other');
        $copy = $value->snippet($snippetOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new SnippetRef('one'), $value->getSnippet());
        $this->assertNotEquals(new SnippetRef('other'), $value->getSnippet());
        $this->assertEquals(new SnippetRef('one'), $value->getSnippetOrCurrent(SnippetVersionSnippetVO::from($snippetOtherValue))->value());
        $this->assertNotEquals(new SnippetRef('other'), $value->getSnippetOrCurrent(SnippetVersionSnippetVO::from($snippetOtherValue))->value());
        $value->unsetSnippet();
        $this->assertEquals(new SnippetRef('other'), $value->getSnippetOrCurrent(SnippetVersionSnippetVO::from($snippetOtherValue))->value());
        $this->assertNotEquals(new SnippetRef('one'), $value->getSnippetOrCurrent(SnippetVersionSnippetVO::from($snippetOtherValue))->value());
        $localeOneValue = 'one';
        $localeOtherValue = 'other';
        $copy = $value->locale($localeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getLocale());
        $this->assertNotEquals('other', $value->getLocale());
        $this->assertEquals('one', $value->getLocaleOrCurrent(SnippetVersionLocaleVO::from($localeOtherValue))->value());
        $this->assertNotEquals('other', $value->getLocaleOrCurrent(SnippetVersionLocaleVO::from($localeOtherValue))->value());
        $value->unsetLocale();
        $this->assertEquals('other', $value->getLocaleOrCurrent(SnippetVersionLocaleVO::from($localeOtherValue))->value());
        $this->assertNotEquals('one', $value->getLocaleOrCurrent(SnippetVersionLocaleVO::from($localeOtherValue))->value());
        $subjectOneValue = 'one';
        $subjectOtherValue = 'other';
        $copy = $value->subject($subjectOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getSubject());
        $this->assertNotEquals('other', $value->getSubject());
        $this->assertEquals('one', $value->getSubjectOrCurrent(SnippetVersionSubjectVO::from($subjectOtherValue))->value());
        $this->assertNotEquals('other', $value->getSubjectOrCurrent(SnippetVersionSubjectVO::from($subjectOtherValue))->value());
        $value->unsetSubject();
        $this->assertEquals('other', $value->getSubjectOrCurrent(SnippetVersionSubjectVO::from($subjectOtherValue))->value());
        $this->assertNotEquals('one', $value->getSubjectOrCurrent(SnippetVersionSubjectVO::from($subjectOtherValue))->value());
        $contentHtmlOneValue = 'one';
        $contentHtmlOtherValue = 'other';
        $copy = $value->contentHtml($contentHtmlOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentHtml());
        $this->assertNotEquals('other', $value->getContentHtml());
        $this->assertEquals('one', $value->getContentHtmlOrCurrent(SnippetVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentHtmlOrCurrent(SnippetVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $value->unsetContentHtml();
        $this->assertEquals('other', $value->getContentHtmlOrCurrent(SnippetVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentHtmlOrCurrent(SnippetVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $contentTextOneValue = 'one';
        $contentTextOtherValue = 'other';
        $copy = $value->contentText($contentTextOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentText());
        $this->assertNotEquals('other', $value->getContentText());
        $this->assertEquals('one', $value->getContentTextOrCurrent(SnippetVersionContentTextVO::from($contentTextOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentTextOrCurrent(SnippetVersionContentTextVO::from($contentTextOtherValue))->value());
        $value->unsetContentText();
        $this->assertEquals('other', $value->getContentTextOrCurrent(SnippetVersionContentTextVO::from($contentTextOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentTextOrCurrent(SnippetVersionContentTextVO::from($contentTextOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(SnippetVersionVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(SnippetVersionVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(SnippetVersionVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(SnippetVersionVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
